import { fileURLToPath } from "node:url";
import { compareLogoOutput, writeLogoOutput } from "../lib/logo-output.js";
import { planLogoGeneration } from "../lib/logo-plan.js";

/**
 * `bun run generate:logos` writes one module per brand logo to `src/generated-logos/logos/`, the
 * barrel `src/generated-logos/index.ts`, and `src/generated-logos/manifest.ts`, from
 * `config/brands.json` and `icons/brand-icons/`. It owns `src/generated-logos/` entirely and removes
 * anything stale there. `--check` (`bun run check:logos`) writes nothing and fails when any
 * generated file is stale, missing, or extra.
 */

const repositoryRoot = fileURLToPath(new URL("../../", import.meta.url));
const check = process.argv.includes("--check");

try {
  const started = performance.now();
  const plan = planLogoGeneration(repositoryRoot);
  if (plan.diagnostics.length > 0) {
    for (const message of plan.diagnostics) console.error(message);
    console.error(
      `Logo generation aborted with ${plan.diagnostics.length} error(s). No generated files were changed.`,
    );
    process.exitCode = 1;
  } else {
    const variants = plan.logos.reduce((sum, logo) => sum + logo.variants.length, 0);
    for (const message of plan.warnings) console.warn(`warning: ${message}`);
    const seconds = ((performance.now() - started) / 1000).toFixed(1);
    if (check) {
      const result = compareLogoOutput(repositoryRoot, plan.files);
      const problems = [
        ...result.stale.map((path) => `${path}: stale`),
        ...result.missing.map((path) => `${path}: missing`),
        ...result.extra.map((path) => `${path}: not generated by generate:logos`),
      ];
      if (problems.length > 0) {
        for (const message of problems.slice(0, 50)) console.error(message);
        if (problems.length > 50) console.error(`… and ${problems.length - 50} more.`);
        console.error(
          `Generated logos are out of date (${problems.length} file(s)). Run \`bun run generate:logos\`.`,
        );
        process.exitCode = 1;
      } else {
        console.log(
          `Generated logos are up to date: ${plan.logos.length} logos, ${variants} variants (${seconds}s).`,
        );
      }
    } else {
      const result = writeLogoOutput(repositoryRoot, plan.files);
      console.log(
        `Generated ${plan.logos.length} logo components with ${variants} variants, the barrel, and the manifest (${result.written} files written, ${result.removed} stale removed, ${seconds}s).`,
      );
    }
  }
} catch (error) {
  console.error(
    `Logo generation failed unexpectedly: ${error instanceof Error ? (error.stack ?? error.message) : String(error)}`,
  );
  process.exitCode = 1;
}
